  1 | /**
  2 |  * 🦙 Llama Player — useGoogleDrive Hook
  3 |  *
  4 |  * Hook React para gerenciar autenticação, navegação e listagem
  5 |  * de arquivos do Google Drive.
  6 |  */
  7 | 
  8 | import { useState, useCallback, useEffect, useRef } from "react";
  9 | import {
 10 |   driveService,
 11 |   type DriveState,
 12 |   type DriveItem,
 13 |   type DriveFolder,
 14 |   type DriveFile,
 15 |   type SyncedPlaylist,
 16 |   isAudioFile,
 17 | } from "../services/googleDrive";
 18 | import type { Track } from "../types";
 19 | 
 20 | // ID do Cliente OAuth — o usuário precisa configurar no .env
 21 | const CLIENT_ID = import.meta.env.VITE_GOOGLE_CLIENT_ID || "";
 22 | 
 23 | const initialState: DriveState = {
 24 |   isAuthenticated: false,
 25 |   isLoading: false,
 26 |   user: null,
 27 |   currentFolder: null,
 28 |   breadcrumbs: [],
 29 |   items: [],
 30 |   error: null,
 31 | };
 32 | 
 33 | export function useGoogleDrive() {
 34 |   const [state, setState] = useState<DriveState>(initialState);
 35 |   const serviceInitialized = useRef(false);
 36 | 
 37 |   /**
 38 |    * Tenta login silencioso ao montar (se houver token salvo).
 39 |    */
 40 |   useEffect(() => {
 41 |     if (!CLIENT_ID) {
 42 |       setState((prev) => ({
 43 |         ...prev,
 44 |         error:
 45 |           "VITE_GOOGLE_CLIENT_ID não configurado. Crie um arquivo .env com seu Client ID do Google Cloud.",
 46 |       }));
 47 |       return;
 48 |     }
 49 | 
 50 |     const init = async () => {
 51 |       try {
 52 |         await driveService.initialize(CLIENT_ID);
 53 |         serviceInitialized.current = true;
 54 | 
 55 |         const loggedIn = await driveService.trySilentLogin(CLIENT_ID);
 56 |         if (loggedIn) {
 57 |           const user = await driveService.getUserInfo();
 58 |           setState((prev) => ({
 59 |             ...prev,
 60 |             isAuthenticated: true,
 61 |             user,
 62 |             isLoading: false,
 63 |             error: null,
 64 |           }));
 65 |           // Carrega a raiz do Drive
 66 |           await loadFolder(null);
 67 |         } else {
 68 |           setState((prev) => ({ ...prev, isLoading: false }));
 69 |         }
 70 |       } catch (err: any) {
 71 |         console.error("[Llama Player] Erro na inicialização do Drive:", err);
 72 |         setState((prev) => ({
 73 |           ...prev,
 74 |           isLoading: false,
 75 |           error: err.message || "Erro ao inicializar Google Drive",
 76 |         }));
 77 |       }
 78 |     };
 79 | 
 80 |     init();
 81 |     // eslint-disable-next-line react-hooks/exhaustive-deps
 82 |   }, []);
 83 | 
 84 |   /**
 85 |    * Faz login com OAuth popup.
 86 |    */
 87 |   const login = useCallback(async () => {
 88 |     if (!serviceInitialized.current) {
 89 |       try {
 90 |         await driveService.initialize(CLIENT_ID);
 91 |         serviceInitialized.current = true;
 92 |       } catch (err: any) {
 93 |         setState((prev) => ({
 94 |           ...prev,
 95 |           error: err.message || "Erro ao inicializar",
 96 |         }));
 97 |         return;
 98 |       }
 99 |     }
100 | 
101 |     setState((prev) => ({ ...prev, isLoading: true, error: null }));
102 | 
103 |     try {
104 |       const success = await driveService.login();
105 |       if (success) {
106 |         const user = await driveService.getUserInfo();
107 |         setState((prev) => ({
108 |           ...prev,
109 |           isAuthenticated: true,
110 |           user,
111 |           isLoading: false,
112 |           error: null,
113 |         }));
114 |         await loadFolder(null);
115 |       } else {
116 |         setState((prev) => ({
117 |           ...prev,
118 |           isLoading: false,
119 |           error: "Login cancelado ou falhou",
120 |         }));
121 |       }
122 |     } catch (err: any) {
123 |       setState((prev) => ({
124 |         ...prev,
125 |         isLoading: false,
126 |         error: err.message || "Erro ao fazer login",
127 |       }));
128 |     }
129 |   }, []);
130 | 
131 |   /**
132 |    * Faz logout.
133 |    */
134 |   const logout = useCallback(async () => {
135 |     try {
136 |       await driveService.logout();
137 |     } catch {
138 |       // Ignora
139 |     }
140 |     setState({ ...initialState });
141 |   }, []);
142 | 
143 |   /**
144 |    * Navega para uma pasta do Drive.
145 |    */
146 |   const loadFolder = useCallback(async (folder: DriveFolder | null) => {
147 |     setState((prev) => ({ ...prev, isLoading: true, error: null }));
148 | 
149 |     try {
150 |       const items = await driveService.listFiles(folder?.id ?? null);
151 | 
152 |       setState((prev) => {
153 |         const breadcrumbs = folder
154 |           ? [...prev.breadcrumbs, folder]
155 |           : [];
156 |         return {
157 |           ...prev,
158 |           currentFolder: folder,
159 |           breadcrumbs,
160 |           items,
161 |           isLoading: false,
162 |           error: null,
163 |         };
164 |       });
165 |     } catch (err: any) {
166 |       setState((prev) => ({
167 |         ...prev,
168 |         isLoading: false,
169 |         error: err.message || "Erro ao carregar pasta",
170 |       }));
171 |     }
172 |   }, []);
173 | 
174 |   /**
175 |    * Navega para uma pasta (entra nela).
176 |    */
177 |   const navigateToFolder = useCallback(
178 |     async (folder: DriveFolder) => {
179 |       await loadFolder(folder);
180 |     },
181 |     [loadFolder]
182 |   );
183 | 
184 |   /**
185 |    * Navega para o breadcrumb (volta).
186 |    */
187 |   const navigateToBreadcrumb = useCallback(
188 |     async (index: number) => {
189 |       const target =
190 |         index === -1
191 |           ? null
192 |           : state.breadcrumbs[index];
193 | 
194 |       setState((prev) => ({
195 |         ...prev,
196 |         breadcrumbs: index === -1 ? [] : prev.breadcrumbs.slice(0, index + 1),
197 |       }));
198 | 
199 |       await loadFolder(target);
200 |     },
201 |     [state.breadcrumbs, loadFolder]
202 |   );
203 | 
204 |   /**
205 |    * Sobe um nível na hierarquia de pastas.
206 |    */
207 |   const goUp = useCallback(async () => {
208 |     const len = state.breadcrumbs.length;
209 |     if (len === 0) return;
210 |     await navigateToBreadcrumb(len - 2);
211 |   }, [state.breadcrumbs.length, navigateToBreadcrumb]);
212 | 
213 |   /**
214 |    * Converte um DriveFile em Track para o player.
215 |    */
216 |   const driveFileToTrack = useCallback((file: DriveFile): Track => {
217 |     const nameWithoutExt = file.name.replace(/\.[^/.]+$/, "");
218 |     return {
219 |       id: `drive-${file.id}`,
220 |       title: nameWithoutExt,
221 |       duration: file.duration || 0,
222 |       src: driveService.getStreamUrl(file.id),
223 |       driveFileId: file.id,
224 |     };
225 |   }, []);
226 | 
227 |   /**
228 |    * Converte múltiplos DriveFiles em Tracks.
229 |    */
230 |   const driveFilesToTracks = useCallback(
231 |     (files: DriveFile[]): Track[] => {
232 |       return files.filter(isAudioFile).map(driveFileToTrack);
233 |     },
234 |     [driveFileToTrack]
235 |   );
236 | 
237 |   /**
238 |    * Obtém apenas os arquivos de áudio da listagem atual.
239 |    */
240 |   const getAudioFiles = useCallback((): DriveFile[] => {
241 |     return state.items.filter(isAudioFile) as DriveFile[];
242 |   }, [state.items]);
243 | 
244 |   /**
245 |    * Busca arquivos de áudio no Drive.
246 |    */
247 |   const searchAudio = useCallback(async (query: string) => {
248 |     setState((prev) => ({ ...prev, isLoading: true, error: null }));
249 |     try {
250 |       const files = await driveService.searchAudio(query);
251 |       // Cria itens falsos para exibir na lista
252 |       const items: DriveItem[] = files;
253 |       setState((prev) => ({
254 |         ...prev,
255 |         items,
256 |         isLoading: false,
257 |         error: null,
258 |       }));
259 |     } catch (err: any) {
260 |       setState((prev) => ({
261 |         ...prev,
262 |         isLoading: false,
263 |         error: err.message || "Erro na busca",
264 |       }));
265 |     }
266 |   }, []);
267 | 
268 |   /**
269 |    * Recarrega a pasta atual (bypass do cache).
270 |    */
271 |   const refreshCurrentFolder = useCallback(async () => {
272 |     await loadFolder(state.currentFolder);
273 |   }, [state.currentFolder, loadFolder]);
274 | 
275 |   /**
276 |    * Limpa o cache de listas do Drive.
277 |    */
278 |   const clearDriveCache = useCallback(() => {
279 |     driveService.clearCache();
280 |   }, []);
281 | 
282 |   /**
283 |    * Sincroniza a playlist com uma pasta do Drive.
284 |    * Retorna a playlist sincronizada com os IDs dos arquivos.
285 |    */
286 |   const syncWithFolder = useCallback(
287 |     async (folder: DriveFolder): Promise<SyncedPlaylist> => {
288 |       return await driveService.syncPlaylistWithFolder(folder.id, folder.name);
289 |     },
290 |     []
291 |   );
292 | 
293 |   /**
294 |    * Obtém playlists sincronizadas.
295 |    */
296 |   const getSyncedPlaylists = useCallback((): SyncedPlaylist[] => {
297 |     return driveService.getSyncedPlaylists();
298 |   }, []);
299 | 
300 |   /**
301 |    * Remove uma playlist sincronizada.
302 |    */
303 |   const removeSyncedPlaylist = useCallback((folderId: string) => {
304 |     driveService.removeSyncedPlaylist(folderId);
305 |   }, []);
306 | 
307 |   /**
308 |    * Carrega tracks de uma playlist sincronizada.
309 |    * Busca os metadados de cada arquivo no Drive e retorna Tracks.
310 |    */
311 |   const loadSyncedPlaylistTracks = useCallback(
312 |     async (synced: SyncedPlaylist): Promise<Track[]> => {
313 |       const tracks: Track[] = [];
314 |       for (const fileId of synced.trackIds) {
315 |         try {
316 |           const meta = await driveService.getFileMetadata(fileId);
317 |           const track = driveFileToTrack(meta);
318 |           tracks.push(track);
319 |         } catch (err) {
320 |           console.warn(
321 |             `[Llama Player] Erro ao carregar arquivo ${fileId}:`,
322 |             err
323 |           );
324 |         }
325 |       }
326 |       return tracks;
327 |     },
328 |     [driveFileToTrack]
329 |   );
330 | 
331 |   return {
332 |     state,
333 |     login,
334 |     logout,
335 |     navigateToFolder,
336 |     navigateToBreadcrumb,
337 |     goUp,
338 |     driveFileToTrack,
339 |     driveFilesToTracks,
340 |     getAudioFiles,
341 |     searchAudio,
342 |     refreshCurrentFolder,
343 |     clearDriveCache,
344 |     syncWithFolder,
345 |     getSyncedPlaylists,
346 |     removeSyncedPlaylist,
347 |     loadSyncedPlaylistTracks,
348 |     CLIENT_ID,
349 |   };
350 | }
351 |
